function checkVerification(result) {
    try {
        var url = result.url();
        var code = result.code();
        var body = result.body() || "";

        // 1. 静态资源（图片切片、广告、css、js等）直接放行
        if (url.indexOf("/photos/") !== -1 || url.indexOf("/media/") !== -1 || url.match(/\.(jpg|jpeg|png|webp|gif|svg|css|js)(\?.*)?$/i)) {
            return result;
        }

        // 2. 正常请求判定：如果 HTTP 状态码为 200，且标题不是 Cloudflare 拦截盾，直接放行
        var isBlocked = (code === 403 || code === 503 || code === 429) || 
            (code === 200 && (body.indexOf("<title>Just a moment...</title>") !== -1 || 
                              body.indexOf("Checking your browser") !== -1 || 
                              body.indexOf("<title>Attention Required") !== -1 ||
                              body.indexOf("cf-turnstile") !== -1));

        if (!isBlocked) {
            return result;
        }

        // 3. 避免频繁弹窗：60秒冷却
        var lastVerified = parseInt(source.get("last_cf_verify_time") || "0");
        var now = new Date().getTime();
        if (now - lastVerified < 60000) {
            return result;
        }

        // 4. 遭遇 Cloudflare 拦截时，唤起浏览器验证窗口
        source.put("last_cf_verify_time", now.toString());
        java.toast("禁漫天堂安全防护，请在窗口中完成验证");

